// Attribute emitted entry bytes using Vite's --sourcemap output, without a visualiser.
// Usage: node perf/bundle-bytes.mjs <dist directory> [entry asset basename]
// A segment owns the generated bytes until the next segment; unmapped bytes stay explicit.
import { readFileSync, readdirSync } from 'node:fs';
import { basename, join, resolve } from 'node:path';

const dist = resolve(process.argv[2] ?? 'dist');
const assets = join(dist, 'assets');
const entry = process.argv[3] ?? readdirSync(assets).find((name) => /^index-.*\.js$/.test(name));
if (!entry) throw new Error(`No entry chunk in ${assets}`);
const file = join(assets, basename(entry));
const code = readFileSync(file, 'utf8');
const map = JSON.parse(readFileSync(`${file}.map`, 'utf8'));
const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
const values = new Map([...alphabet].map((c, i) => [c, i]));
function decode(segment) {
  const out = [];
  let value = 0;
  let shift = 0;
  for (const char of segment) {
    const digit = values.get(char);
    if (digit === undefined) throw new Error(`Invalid VLQ digit: ${char}`);
    value += (digit & 31) * 2 ** shift;
    if (digit & 32) shift += 5;
    else {
      out.push(value & 1 ? -Math.floor(value / 2) : value / 2);
      value = 0;
      shift = 0;
    }
  }
  if (shift) throw new Error('Unfinished VLQ segment');
  return out;
}
const bytes = new Map();
const add = (source, text) => bytes.set(source, (bytes.get(source) ?? 0) + Buffer.byteLength(text));
const lines = code.split('\n');
const mappings = map.mappings.split(';');
let source = 0;
for (let lineIndex = 0; lineIndex < lines.length; lineIndex += 1) {
  const line = lines[lineIndex];
  let column = 0;
  let owner = '(unmapped)';
  for (const segment of (mappings[lineIndex] ?? '').split(',').filter(Boolean)) {
    const fields = decode(segment);
    const next = column + fields[0];
    add(owner, line.slice(column, next));
    column = next;
    if (fields.length > 1) {
      source += fields[1];
      owner = map.sources[source];
    } else owner = '(unmapped)';
  }
  add(owner, line.slice(column));
  if (lineIndex < lines.length - 1) add('(unmapped)', '\n');
}
const modules = [...bytes].map(([module, bytes]) => ({ module, bytes })).sort((a, b) => b.bytes - a.bytes);
const total = Buffer.byteLength(code);
if (modules.reduce((n, m) => n + m.bytes, 0) !== total) throw new Error('Byte attribution did not reconcile');
console.log(JSON.stringify({ entry: basename(file), bytes: total, modules }, null, 2));
